        return root;
    }

    static TreeNode build(List<String> tokens) {
        if (tokens.isEmpty() || tokens.get(0).equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        ArrayList<TreeNode> queue = new ArrayList<>();
        queue.add(root);
        int head = 0, i = 1;
        while (head < queue.size() && i < tokens.size()) {
            TreeNode node = queue.get(head++);
            if (i < tokens.size()) {
                if (!tokens.get(i).equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(tokens.get(i)));
                    queue.add(node.left);
                }
                i++;
            }
            if (i < tokens.size()) {
                if (!tokens.get(i).equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(tokens.get(i)));
                    queue.add(node.right);
                }
                i++;
            }
        }
        return root;
    }

    static String serialize(TreeNode root) {
        if (root == null) return "null";
        ArrayList<String> out = new ArrayList<>();
        ArrayList<TreeNode> queue = new ArrayList<>();
        queue.add(root);
        int head = 0;
        while (head < queue.size()) {
            TreeNode node = queue.get(head++);
            if (node == null) {
                out.add("null");
            } else {
                out.add(String.valueOf(node.val));
                queue.add(node.left);
                queue.add(node.right);
            }
        }
        while (out.get(out.size() - 1).equals("null")) out.remove(out.size() - 1);
        return String.join(" ", out);
    }

